# the correlations of one score with the other scales, closest first, with
# the block of each scale and the size of the correlation
correlation_table &lt;- \(correlations) {
  correlations |&gt;
    left_join(scales, by = "scale") |&gt;
    mutate(size = case_when(abs(r) &gt;= .50 ~ "strong",
                            abs(r) &gt;= .30 ~ "moderate",
                            abs(r) &gt;= r_critical ~ "small",
                            .default = "not significant")) |&gt;
    arrange(desc(abs(r))) |&gt;
    select(scale = label, block, r, size) |&gt;
    mutate(r = round(r, 2))
}




# how many items of each scale a composite pools
items_by_scale &lt;- \(items) {
  tibble(scale = str_remove(items, "[0-9]+$")) |&gt;
    count(scale, name = "items") |&gt;
    left_join(scales, by = "scale") |&gt;
    arrange(match(scale, scales$scale)) |&gt;
    select(scale = label, block, items)
}




# the correlations of the 23 scale scores as a lower triangle, in the order
