    ggplot(aes(column, row, fill = r)) +
    geom_tile(colour = "white", linewidth = .6) +
    geom_text(aes(label = apa(r)), size = 2.4) +
    scale_fill_gradient2(low = "#e34948", mid = "#f0efec", high = "#2a78d6",
                         limits = c(-1, 1)) +
    labs(x = NULL, y = NULL, fill = "r") +
    theme_minimal(base_size = 11) +
    theme(panel.grid = element_blank(),
          axis.text.x = element_text(angle = 45, hjust = 1))
}




# the items of each score: Women Attitude without its two items at the
# ceiling (Chapter 2)
scored_items &lt;- map(scale_items, \(items) setdiff(items, ceiling_items))

# the item analysis of the textbooks at one wave (Nunnally & Bernstein,
# 1994; Clark & Watson, 1995): for every item its correlation with the sum
# of the other items (corrected item-total correlation) and the change in
# α without it, beside the average correlation between the items
item_analysis &lt;- \(answers) {
  fit &lt;- psych::alpha(answers, warnings = FALSE)
  tibble(item      = str_c("item ", str_extract(names(answers), "[0-9]+$")),
         average_r = fit$total$average_r,
         r_rest    = fit$item.stats$r.drop,
         change    = if (ncol(answers) &gt; 2) {
           fit$alpha.drop$raw_alpha - fit$total$raw_alpha
         } else NA_real_)
}

# a signed change in α, as "+.016"
signed &lt;- \(x) str_c(if_else(x &lt; 0, "−", "+"), apa(abs(x), 3))

# one row per wave: the average correlation between the items, the weakest
# item with its correlation with the rest, how many items lie below .30,
# and the item without which α would change most upwards
item_table &lt;- \(analysis) {
  analysis |&gt;
    summarise(average_r = apa(first(average_r)),
              weakest   = str_c(item[which.min(r_rest)], ": ",
                                apa(min(r_rest))),
              below_30  = sum(r_rest &lt; .30),
              without   = if (all(is.na(change))) "–" else {
                str_c(item[which.max(change)], ": ", signed(max(change)))
              },
              .by = wave)
}

# the waves at which something holds, as "T0 and T2"
waves_where &lt;- \(wave, holds) str_flatten_comma(unique(wave[holds]),
                                                last = " and ")

# what the item checks say, in three sentences
item_sentence &lt;- \(analysis) {
  r &lt;- distinct(analysis, wave, average_r)
  average &lt;- str_c("On average the items correlate at ", apa(min(r$average_r)),
                   " to ", apa(max(r$average_r)))
  average &lt;- if (all(between(r$average_r, .15, .50))) {
    str_c(average, ", within the .15 to .50 that Clark and Watson (1995) ",
          "recommend.")
  } else if (all(r$average_r &gt; .50)) {
    str_c(average, ", above the .50 from which Clark and Watson (1995) ",
          "see items come close to saying the same.")
  } else {
    str_c(average, c(
      if (any(r$average_r &gt; .50)) {
        str_c(", above .50 at ", waves_where(r$wave, r$average_r &gt; .50))
      },
      if (any(r$average_r &lt; .15)) {
        str_c(", below .15 at ", waves_where(r$wave, r$average_r &lt; .15))
      }) |&gt; str_flatten(), " (Clark and Watson, 1995, recommend .15 to .50).")
  }
  weak &lt;- analysis |&gt;
    filter(r_rest &lt; .30) |&gt;
    summarise(text = str_c(first(item), " (", waves_where(wave, TRUE),
                           ", down to ", apa(min(r_rest)), ")"),
              .by = item)
  rest &lt;- if (nrow(weak) == 0) {
    str_c("Every item correlates at least .30 with the rest of the scale, ",
          "at every wave (lowest ", apa(min(analysis$r_rest)), ").")
  } else {
    str_c(str_flatten_comma(weak$text, last = " and "),
          if (nrow(weak) == 1) " correlates" else " correlate",
          " less than .30 with the rest of the scale.") |&gt;
      str_replace("^item", "Item")
  }
  rising &lt;- analysis |&gt; filter(change &gt; .01)
  without &lt;- if (all(is.na(analysis$change))) {
    "With two items, neither can be left out."
  } else if (nrow(rising) == 0) {
    "Without any one item, α would rise by .01 or less at every wave."
  } else {
    str_c("Without ", str_flatten_comma(unique(rising$item), last = " or "),
          ", α would rise by up to ", apa(max(rising$change), 3), " (at ",
          waves_where(rising$wave, TRUE), "): ",
          if (n_distinct(rising$item) == 1) "this item goes" else
            "these items go",
          " less with the scale than the others.")
  }
  str_c(average, " ", rest, " ", without)
}




# α and ω of a set of items at each wave, as in Step 2
reliability_by_wave &lt;- \(items) {
  list_df |&gt;
    map(\(wave) {
      answers &lt;- select(wave, all_of(items))
      tibble(alpha = if (length(items) &gt; 1) {
               psych::alpha(answers, warnings = FALSE)$total$raw_alpha
             } else NA_real_,
             omega = if (length(items) &gt; 2) {
               psych::omega(answers, nfactors = 1, plot = FALSE)$omega.tot
             } else NA_real_)
    }) |&gt;
    list_rbind(names_to = "wave")
}

# α and ω in words, judged on the unrounded values (5.1)
reliability_text &lt;- \(reliability) {
  a &lt;- reliability$alpha
  text &lt;- str_c("α ", apa(min(a)), " to ", apa(max(a)))
  text &lt;- if (all(a &gt;= .70)) str_c(text, ", acceptable at every wave") else {
    str_c(text, ", below .70 at ", waves_where(reliability$wave, a &lt; .70),
          if (any(a &lt; .60)) {
            str_c(" (poor at ", waves_where(reliability$wave, a &lt; .60), ")")
          })
  }
  omega &lt;- reliability$omega
  if (all(is.na(omega))) return(text)
  gap &lt;- omega - a
  str_c(text, "; ω ", apa(min(omega)), " to ", apa(max(omega)),
        if (any(gap &gt; .05)) {
          str_c(", more than .05 above α at ",
                waves_where(reliability$wave, gap &gt; .05))
        })
}

# the item checks in words, for the path
item_text &lt;- \(analysis) {
  weak &lt;- unique(analysis$item[analysis$r_rest &lt; .30])
  rising &lt;- unique(analysis$item[!is.na(analysis$change) &
                                   analysis$change &gt; .01])
  c(if (length(weak) == 0) "every item .30 or more with the rest" else {
      str_c(str_flatten_comma(weak, last = " and "),
            " below .30 with the rest")
    },
    if (length(rising) &gt; 0) {
      str_c("without ", str_flatten_comma(rising, last = " or "),
            " α would rise by more than .01")
    }) |&gt;
    str_flatten("; ")
}

# the path of a scale through the four steps, from the computations of the
# steps themselves
scale_path &lt;- \(scale) {
  items &lt;- scored_items[[scale]]
  labels &lt;- set_names(scales$label, scales$scale)
  r &lt;- t0 |&gt;
    select(all_of(scales$scale)) |&gt;
    cor(use = "pairwise.complete.obs")
  others &lt;- r[scale, setdiff(colnames(r), scale)]
  closest &lt;- names(which.max(abs(others)))
  checks &lt;- if (length(items) &gt; 1) {
    list_df |&gt;
      map(\(wave) item_analysis(select(wave, all_of(items)))) |&gt;
      list_rbind(names_to = "wave") |&gt;
      item_text()
  } else "one item: nothing to check"
  tribble(
    ~Step, ~Question, ~Result, ~Next,
    "2", "How consistently do the items measure at each wave?",
    if (length(items) == 1) "one item: no α within a wave" else {
      reliability_text(reliability_by_wave(items))
    }, "item checks",
    "2", "Do the items pass the item checks?", checks, "correlations",
    "3", "Which scale goes with it most closely in January?",
    str_c(labels[closest], " (r = ", apa(others[closest]), ")"),
    "what follows",
    "4", "Where next?",
    str_c("Table 1; an outcome of Chapters 9, 10 and 14",
          if (scale %in% names(model_items)) "; a latent factor (Chapter 6)"),
    "")
}

# the path of a composite: Step 2 computed, Steps 3 and 4 in words
composite_path &lt;- \(items, step3, step4) {
  tribble(
    ~Step, ~Question, ~Result, ~Next,
    "2", "How consistently do the pooled items measure at each wave?",
    reliability_text(reliability_by_wave(items)), "its scales",
    "3", step3[1], step3[2], "what follows",
    "4", "Where next?", step4, "")
}




# α of each scale at each wave, with dashed lines at .60 and .70
wave_colours &lt;- c(T0 = "#2a78d6", T1 = "#eb6834", T2 = "#1baf7a",
                  T3 = "#eda100")
plot_reliability &lt;- \(reliability) {
  reliability |&gt;
    filter(!is.na(alpha)) |&gt;
    left_join(scales, by = "scale") |&gt;
    mutate(label = factor(label, levels = rev(scales$label))) |&gt;
    ggplot(aes(alpha, label, colour = wave)) +
    geom_vline(xintercept = c(.60, .70), linetype = "dashed",
               colour = "grey60") +
    geom_point(size = 2.4) +
    scale_colour_manual(values = wave_colours) +
    scale_x_continuous(limits = c(.5, 1), breaks = seq(.5, 1, .1),
                       labels = \(x) apa(x, 1)) +
    labs(x = "Cronbach's α", y = NULL, colour = NULL) +
    theme_minimal(base_size = 11) +
    theme(panel.grid.minor = element_blank(), legend.position = "top")
}

18.2 Data and tools
Which data? The final pool of Chapter 17 (loaded above), the questionnaires of T0 and of all four waves, one data set each:

items_T0 &lt;- df |&gt; filter(Occasion == "T0")
list_df  &lt;- split(df, df$Occasion)

Which results of the pipeline script? The bootstrap of the hierarchical solution of the final pool, and the bootstraps of the composites at each wave:

final &lt;- readRDS("cache/structure_final.rds")

The script stores the T0 solution of the final pool (assignment), the stability of every item at both levels of its bootstrap (final_items), the structural consistency of the communities (final_lower) and of the factors (final_higher), and for each wave the bootstrap of the composites (composite_boot).
Which tools? What runs in this chapter is written out below. The pipeline script, the functions it calls, and three small functions for the figures are shown once here:

Pipeline scriptNetwork functionsItem response functionsComposite functionsItem stabilityComposites over the wavesTest information



# Post hoc psychometrics: the bootstraps and the chain of item selections
# of Chapters 16 to 18. The T0 questionnaires calibrate every step; the
# composites are bootstrapped again at each wave.
# Run from swt-website/ after Chapter 2:  Rscript scripts/structure_pipeline.R

source("R/packages.R")
source("R/settings.R")
df &lt;- readRDS("cache/df.rds")           # one row per questionnaire (Chapter 2)
item_names &lt;- names(select(df, ListenOther1:CompetenceNonFrustrated4))
source("R/structure_pool.R")            # item pruning (Chapter 15)
source("R/structure_ega.R")             # network analyses (Chapter 16)
source("R/structure_irt.R")             # redundancy and IRT (Chapter 17)
source("R/structure_composites.R")      # composites (Chapter 18)

# Chapter 16: bootstrap until every item is stable, then bootstrap the
# hierarchical solution of the stable items. The items are ordered by
# community and stability; louvain and the bootstrap draws depend on the
# order of the items.
pool      &lt;- structure_pool(df)
converged &lt;- converge_ega(items_at(df, "T0", pool))
stable    &lt;- converged$stability |&gt;
  arrange(community, desc(stability)) |&gt;
  pull(item)
boot_hier &lt;- boot_hier_ega(items_at(df, "T0", stable))

saveRDS(list(pool        = pool,
             passes      = converged$passes,
             stability   = converged$stability,
             stable      = stable,
             hier_items  = hier_item_stability(boot_hier),
             hier_lower  = structural_consistency(boot_hier, "lower_order"),
             hier_higher = structural_consistency(boot_hier, "higher_order")),
        "cache/structure_ega.rds")

# Chapter 17: GRM per community and UVA on the persons who answered all
# stable items; the communities come from the bootstrap above
communities &lt;- hier_item_stability(boot_hier) |&gt;
  select(item, community = lower, stability = stability_lower)
calibration &lt;- items_at(df, "T0", communities$item) |&gt; drop_na()
pruned      &lt;- community_discrimination(calibration, communities) |&gt;
  prune_items(redundant_sets(calibration))
final_pool  &lt;- pruned |&gt; filter(keep) |&gt; pull(item)

saveRDS(list(pruned = pruned, final_pool = final_pool),
        "cache/structure_irt.rds")

# Chapter 18: the hierarchical solution of the final pool and its
# bootstrap; the composites of its communities, bootstrapped at each wave
final_T0   &lt;- items_at(df, "T0", final_pool)
assignment &lt;- hier_ega(final_T0, hier_seeds[["T0"]]) |&gt;
  hier_assignment() |&gt;
  arrange(higher, lower, item)
boot_final &lt;- boot_hier_ega(final_T0)
composites &lt;- composite_items(assignment)

boot_wave &lt;- \(wave) boot_ega(composite_scores(df, composites, wave))
composite_boot &lt;- tibble(wave = names(hier_seeds)) |&gt;
  mutate(boot        = map(wave, boot_wave),
         n           = map_int(boot, \(b) b$EGA$n),
         dimensions  = map_int(boot, \(b) b$EGA$n.dim),
         stability   = map(boot, item_stability),
         consistency = map(boot, structural_consistency),
         frequency   = map(boot, \(b) as_tibble(b$frequency))) |&gt;
  select(-boot)

saveRDS(list(assignment     = assignment,
             final_items    = hier_item_stability(boot_final),
             final_lower    = structural_consistency(boot_final,
                                                     "lower_order"),
             final_higher   = structural_consistency(boot_final,
                                                     "higher_order"),
             composite_boot = composite_boot),
        "cache/structure_final.rds")




# Exploratory graph analysis (Chapters 16 and 18). The network of the items
# comes from the graphical lasso on pairwise correlations ("auto": Pearson
# for items with eleven answer categories); walktrap finds its communities,
# louvain the two levels of the hierarchical solution. Bootstraps draw 500
# samples from a normal distribution with the observed correlations, with
# seed 42; each hierarchical solution has a seed of its own per wave.
# Louvain draws random numbers (also when EGA checks a sample for a single
# dimension), which parallel workers do not seed: the bootstraps run in one
# process (ncores = 1), so that they repeat exactly.

# the label of an item's scale (needs `scales`, Chapter 2)
scale_label &lt;- \(item) {
  scales$label[match(str_remove(item, "[0-9]+$"), scales$scale)]
}

# the answers of one wave to some items
items_at &lt;- \(data, wave, items) {
  data |&gt;
    filter(Occasion == wave) |&gt;
    select(all_of(items))
}

# a bootstrap of the network and its communities
boot_ega &lt;- \(items) {
  set.seed(42)
  bootEGA(items, iter = 500, type = "parametric", corr = "auto",
          model = "glasso", algorithm = "walktrap", na.data = "pairwise",
          seed = 42, ncores = 1, verbose = FALSE, plot.itemStability = FALSE)
}

# how often each item falls into its own community across the bootstrap
# samples; community = the community in the observed data
item_stability &lt;- \(boot, level = NULL) {
  s &lt;- itemStability(boot, IS.plot = FALSE)
  if (!is.null(level)) s &lt;- s[[level]]
  stability &lt;- s$item.stability$empirical.dimensions
  tibble(item      = names(stability),
         community = as.integer(s$membership$empirical[item]),
         stability = unname(stability))
}

# drop the items below the rule and bootstrap the rest again, until every
# item reaches the rule (at most 25 passes); returns each pass and the
# stability of the items that stay
converge_ega &lt;- \(items, rule = .60, pass = 1) {
  stability &lt;- item_stability(boot_ega(items))
  dropped   &lt;- stability$item[stability$stability &lt; rule]
  this_pass &lt;- tibble(pass, items_in = ncol(items),
                      below = length(dropped),
                      min_stability  = min(stability$stability),
                      mean_stability = mean(stability$stability),
                      dropped = list(dropped))
  if (length(dropped) == 0 || pass == 25) {
    return(list(passes = this_pass, stability = stability))
  }
  rest &lt;- converge_ega(select(items, -all_of(dropped)), rule, pass + 1)
  rest$passes &lt;- bind_rows(this_pass, rest$passes)
  rest
}

# hierarchical EGA of one wave: communities of items (lower order) and
# communities of the community scores (higher order)
hier_seeds &lt;- c(T0 = 123, T1 = 456, T2 = 789, T3 = 101112)

hier_ega &lt;- \(items, seed) {
  set.seed(seed)
  hierEGA(items, scores = "network", loading.method = "revised",
          corr = "auto", na.data = "pairwise", model = "glasso",
          plot.EGA = FALSE, verbose = FALSE)
}

hier_assignment &lt;- \(hier) {
  hier$dim.variables |&gt;
    as_tibble() |&gt;
    transmute(item = items, lower = as.integer(lower),
              higher = as.integer(higher))
}

hier_size &lt;- \(hier) {
  tibble(lower  = hier$lower_order$n.dim,
         higher = hier$higher_order$n.dim,
         TEFI   = hier$TEFI)
}

# the share of item pairs that two partitions treat alike (both together or
# both apart): 1 if the partitions are the same, whatever their numbers
pair_agreement &lt;- \(a, b) {
  together_a &lt;- outer(a, a, "==")
  together_b &lt;- outer(b, b, "==")
  mean((together_a == together_b)[upper.tri(together_a)])
}

# a bootstrap of the hierarchical solution
boot_hier_ega &lt;- \(items) {
  set.seed(42)
  bootEGA(items, iter = 500, type = "parametric", corr = "auto",
          model = "glasso", na.data = "pairwise", EGA.type = "hierEGA",
          scores = "network", loading.method = "revised", seed = 42,
          ncores = 1, verbose = FALSE, plot.itemStability = FALSE)
}

# item stability at both levels, in the order of the communities
hier_item_stability &lt;- \(boot) {
  inner_join(item_stability(boot, "lower_order"),
             item_stability(boot, "higher_order"),
             by = "item", suffix = c("_lower", "_higher")) |&gt;
    rename(lower = community_lower, higher = community_higher) |&gt;
    arrange(higher, lower, desc(stability_lower))
}

# how often each community is found again with exactly the same items
structural_consistency &lt;- \(boot, level = NULL) {
  s &lt;- dimensionStability(boot, IS.plot = FALSE)
  if (!is.null(level)) s &lt;- s[[level]]
  consistency &lt;- s$dimension.stability$structural.consistency
  tibble(community   = as.integer(names(consistency)),
         consistency = unname(consistency))
}




# Redundancy and item response theory (Chapters 17 and 18). A graded
# response model (GRM) per community gives each item its discrimination a;
# unique variable analysis (UVA) finds pairs of items so close in the
# network that one of them says nothing new.

# a unidimensional GRM on the persons who answered every item
grm_fit &lt;- \(items) {
  mirt(drop_na(items), 1, itemtype = "graded", verbose = FALSE)
}

discrimination &lt;- \(fit) {
  a &lt;- coef(fit, IRTpars = TRUE, simplify = TRUE)$items[, "a"]
  tibble(item = names(a), a = unname(a))
}

# the discrimination of every item, from one GRM per community; a GRM
# needs at least three items, so items of smaller communities get NA
community_discrimination &lt;- \(items, communities) {
  grm &lt;- communities |&gt;
    filter(n() &gt;= 3, .by = community) |&gt;
    summarise(fit = list(grm_fit(items[item])), .by = community) |&gt;
    mutate(reliability = map_dbl(fit, marginal_rxx),
           a           = map(fit, discrimination)) |&gt;
    select(community, reliability, a) |&gt;
    unnest(a)
  communities |&gt;
    left_join(grm, by = c("community", "item"))
}

# sets of redundant items: a weighted topological overlap of .25 or more
redundant_sets &lt;- \(items) {
  uva &lt;- UVA(items, uva.method = "MBR", cut.off = .25, reduce = FALSE,
             verbose = FALSE)
  imap(uva$redundant, \(partners, item) sort(unique(c(item, partners))))
}

# from a redundant set keep the item with the highest discrimination, then
# the highest bootstrap stability, then the first in the alphabet
keep_one &lt;- \(set, items) {
  items |&gt;
    filter(item %in% set) |&gt;
    arrange(desc(a), desc(stability), item) |&gt;
    slice(1) |&gt;
    pull(item)
}

# the items that stay: drop the poorly discriminating (a &lt; .50) and all but
# one item of each redundant set; items has item, a and stability
prune_items &lt;- \(items, sets) {
  redundant &lt;- map(sets, \(set) setdiff(set, keep_one(set, items))) |&gt;
    list_c()
  items |&gt;
    mutate(poor = !is.na(a) & a &lt; .50,
           redundant = item %in% redundant,
           keep = !poor & !redundant)
}

# the thresholds of each item of a GRM: b1, b2, ..., the trait levels at
# which an answer above a category becomes more likely than one at or below
thresholds &lt;- \(fit) {
  coef(fit, IRTpars = TRUE, simplify = TRUE)$items |&gt;
    as_tibble(rownames = "item") |&gt;
    select(item, starts_with("b")) |&gt;
    pivot_longer(-item, names_to = "threshold", values_to = "b",
                 values_drop_na = TRUE)
}

# the information of all items of a GRM together, over the trait levels
test_information &lt;- \(fit, theta = seq(-4, 4, by = .1)) {
  tibble(theta = theta, information = testinfo(fit, matrix(theta)))
}




# Composites of the final structure (Chapter 18): one score per community
# of the final item pool, their reliability, how the composites group into
# factors, and a table of every item. Needs R/structure_ega.R and
# R/structure_irt.R.

# a community takes the short name of its scale; a community that mixes
# scales is "Connection" (listening, being moved, being understood)
scale_short &lt;- c(
  ListenOther = "Listen", ListenSelf = "Listen", KamaMuta = "KamaMuta",
  Understood = "Underst", Resonance = "Resonance", Rogerian = "Rogerian",
  ParadoxMindset = "Paradox", IntellectualHumility = "IntHumility",
  ToleranceDiversity = "Tolerance", Flourishing = "Flourishing",
  Empowerment = "Empowerment", AutonomySatisfaction = "AutonomySat",
  CompetenceSatisfaction = "CompetenceSat"
)

community_name &lt;- \(items) {
  scale &lt;- unique(str_remove(items, "[0-9]+$"))
  if (length(scale) &gt; 1) return("Connection")
  unname(coalesce(scale_short[scale], scale))
}

# a factor is named after its communities
factor_name &lt;- \(communities) {
  communities &lt;- as.character(communities)
  case_when("Connection" %in% communities  ~ "Engagement",
            "Flourishing" %in% communities ~ "Well-being and agency",
            .default = str_flatten(communities, " & "))
}

# the items of each composite, in the order of the communities
composite_items &lt;- \(assignment) {
  assignment |&gt;
    arrange(lower) |&gt;
    mutate(composite = community_name(item), .by = lower) |&gt;
    mutate(composite = fct_inorder(composite))
}

# composite scores of one wave: the mean of the answered items
composite_scores &lt;- \(data, composites, wave) {
  answers &lt;- data |&gt; filter(Occasion == wave)
  split(composites$item, composites$composite) |&gt;
    map(\(items) rowMeans(answers[items], na.rm = TRUE)) |&gt;
    as_tibble()
}

# Cronbach's alpha on the persons who answered every item
cronbach &lt;- \(items) {
  items &lt;- drop_na(items)
  k &lt;- ncol(items)
  v &lt;- var(items)
  k / (k - 1) * (1 - sum(diag(v)) / sum(v))
}

# the correlation of each item with the mean of the other items
item_rest &lt;- \(items) {
  map_dbl(names(items), \(item) {
    rest &lt;- rowMeans(items[setdiff(names(items), item)], na.rm = TRUE)
    cor(items[[item]], rest, use = "pairwise.complete.obs")
  })
}

# Fisher information of each item of a GRM at three trait levels
item_information &lt;- \(fit, theta = c(-2, 0, 2)) {
  items &lt;- colnames(extract.mirt(fit, "data"))
  map(seq_along(items), \(i) {
    info &lt;- iteminfo(extract.item(fit, i), Theta = matrix(theta))
    tibble(item = items[i], theta = theta, information = info)
  }) |&gt;
    list_rbind()
}




# the bootstrap stability of every item in its community and in its
# factor, one panel per community
plot_item_stability &lt;- \(items) {
  items |&gt;
    pivot_longer(c(stability_lower, stability_higher),
                 names_to = "level", values_to = "stability") |&gt;
    mutate(level = if_else(level == "stability_lower",
                           "in its community", "in its factor"),
           item  = fct_inorder(item)) |&gt;
    ggplot(aes(x = stability, y = fct_rev(item), colour = level)) +
    geom_point(size = 2.2) +
    facet_grid(lower ~ ., scales = "free_y", space = "free_y") +
    scale_colour_manual(values = c("in its community" = "#1baf7a",
                                   "in its factor"    = "#eda100")) +
    scale_x_continuous(limits = c(0, 1)) +
    labs(x = "item stability (share of 500 bootstrap samples)", y = NULL,
         colour = NULL) +
    theme_minimal(base_size = 11) +
    theme(legend.position = "top", panel.grid.minor = element_blank(),
          strip.text.y = element_text(angle = 0))
}




# the stability of each composite in its dimension at each wave, one panel
# per T0 factor; open: the composite sits in the other factor
wave_colours &lt;- c(T0 = "#2a78d6", T1 = "#eb6834", T2 = "#1baf7a",
                  T3 = "#eda100")
plot_composite_waves &lt;- \(waves) {
  waves |&gt;
    mutate(place = if_else(factor == canonical, "in its T0 factor",
                           "in the other factor")) |&gt;
    ggplot(aes(wave, stability, group = composite)) +
    geom_line(colour = "grey70", linewidth = .6) +
    geom_point(aes(colour = wave, shape = place), size = 2.6) +
    ggrepel::geom_text_repel(data = \(d) filter(d, wave == "T3"),
                             aes(label = composite), direction = "y",
                             nudge_x = .15, hjust = 0, size = 3.2,
                             segment.colour = "grey80") +
    facet_wrap(~ canonical) +
    scale_colour_manual(values = wave_colours, guide = "none") +
    scale_shape_manual(values = c("in its T0 factor" = 16,
                                  "in the other factor" = 1)) +
    scale_x_discrete(expand = expansion(add = c(.3, 1.8))) +
    scale_y_continuous(limits = c(0, 1)) +
    labs(x = NULL, y = "stability in its dimension", shape = NULL) +
    theme_minimal(base_size = 11) +
    theme(legend.position = "top", panel.grid.minor = element_blank())
}




# the information of all items of a composite together, from three
# standard deviations below to three above the mean
plot_information &lt;- \(grm, theta = seq(-3, 3, by = .05)) {
  grm |&gt;
    mutate(curve = map(fit, \(f)
      tibble(theta = theta, information = testinfo(f, matrix(theta))))) |&gt;
    select(composite, curve) |&gt;
    unnest(curve) |&gt;
    ggplot(aes(x = theta, y = information)) +
    geom_vline(xintercept = 0, colour = "grey80", linewidth = .4) +
    geom_line(colour = "#2a78d6", linewidth = .7) +
    facet_wrap(~ composite, ncol = 3, scales = "free_y") +
    labs(x = "trait level θ (standard deviations)",
         y = "test information") +
    theme_minimal(base_size = 11) +
    theme(panel.grid.minor = element_blank())
}
